
from web3 import Web3

# Connect to Ganache
ganache_url = "http://127.0.0.1:7545"

web3 = Web3(Web3.HTTPProvider(ganache_url))

# Set default account
web3.eth.default_account = web3.eth.accounts[0]

# ABI
abi = [
  {
    "inputs": [
      {
        "internalType": "string",
        "name": "hash",
        "type": "string"
      }
    ],
    "name": "storeHash",
    "outputs": [],
    "stateMutability": "nonpayable",
    "type": "function"
  },
  {
    "inputs": [
      {
        "internalType": "string",
        "name": "hash",
        "type": "string"
      }
    ],
    "name": "verifyHash",
    "outputs": [
      {
        "internalType": "bool",
        "name": "",
        "type": "bool"
      }
    ],
    "stateMutability": "view",
    "type": "function"
  }
]

# BYTECODE
bytecode = ""

# Create contract
CertificateContract = web3.eth.contract(
    abi=abi,
    bytecode=bytecode
)

# Deploy contract
tx_hash = CertificateContract.constructor().transact()

# Wait for deployment
tx_receipt = web3.eth.wait_for_transaction_receipt(tx_hash)

# Print deployed contract address
print("Contract Deployed Successfully!")
print("Contract Address:", tx_receipt.contractAddress)